import{_ as t,o as a,c as o,a2 as h}from"./chunks/framework.BGlkWkwp.js";const u=JSON.parse('{"title":"MenuSheet","description":"","frontmatter":{},"headers":[],"relativePath":"workbench/menu-sheet.md","filePath":"workbench/menu-sheet.md"}'),n={name:"workbench/menu-sheet.md"};function r(d,e,s,i,l,c){return a(),o("div",null,[...e[0]||(e[0]=[h('<h1 id="menusheet" tabindex="-1">MenuSheet <a class="header-anchor" href="#menusheet" aria-label="Permalink to &quot;MenuSheet&quot;">​</a></h1><p>MenuSheet shows a menu in a sheet that comes up from the bottom of a narrow screen.</p><h2 id="when-to-use" tabindex="-1">When to use <a class="header-anchor" href="#when-to-use" aria-label="Permalink to &quot;When to use&quot;">​</a></h2><p>Use it on a phone for the same model that an <a href="./app-menu">AppMenu</a> shows on a wider screen, so that the application describes its menu once. It is placed in the frame of the application, which must be a positioned element, as for a <a href="./../components/sheet">Sheet</a>. The application opens it with <code>open</code>.</p><h2 id="props" tabindex="-1">Props <a class="header-anchor" href="#props" aria-label="Permalink to &quot;Props&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Prop</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><code>items</code></td><td>required</td><td>The model, <code>MenuModel[]</code></td></tr><tr><td><code>onselect</code></td><td></td><td>Called with the id of the chosen item</td></tr><tr><td><code>open</code></td><td><code>false</code></td><td>The sheet shows (bindable)</td></tr><tr><td><code>onclose</code></td><td></td><td>Called when the sheet closes</td></tr><tr><td><code>title</code></td><td>&quot;Menu&quot;</td><td>The title in the head of the sheet</td></tr></tbody></table><h2 id="contract" tabindex="-1">Contract <a class="header-anchor" href="#contract" aria-label="Permalink to &quot;Contract&quot;">​</a></h2><p>It is a Sheet at half or full height, with a <a href="./../components/toolbar">Toolbar</a> head that holds the title, and the model as a <a href="./menu-list">MenuList</a> with <code>inline</code>: a submenu takes the place of the list, under a row that goes back. The first item takes the focus when it opens, and the keys are a MenuList&#39;s. Choosing an item reports its id and closes the sheet; a drag below the lowest height and Escape close it too.</p><h2 id="example" tabindex="-1">Example <a class="header-anchor" href="#example" aria-label="Permalink to &quot;Example&quot;">​</a></h2><figure class="kata-example"><iframe src="/kata/examples/menu-sheet/" title="MenuSheet" loading="lazy" style="width:100%;height:32rem;border:1px solid var(--vp-c-divider);border-radius:8px;"></iframe><figcaption><a href="/kata/examples/menu-sheet/" target="_blank" rel="noopener">MenuSheet</a></figcaption></figure>',10)])])}const m=t(n,[["render",r]]);export{u as __pageData,m as default};
